Nothing like this exists in the repo yet, so here it is, stdlib only. I ran the self-check and it passes; I haven't added it to any file.

```python
import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,), sleep=time.sleep):
    """Call fn(); on failure wait base * 2**n seconds (capped, full jitter) and retry."""
    for n in range(attempts):
        try:
            return fn()
        except exceptions:
            if n == attempts - 1:
                raise
            sleep(random.uniform(0, min(cap, base * 2 ** n)))


def demo():
    calls, waits = [], []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise OSError("nope")
        return "ok"

    assert retry(flaky, sleep=waits.append) == "ok"
    assert len(calls) == 3 and len(waits) == 2
    assert waits[0] <= 0.5 and waits[1] <= 1.0

    try:
        retry(lambda: 1 / 0, attempts=2, sleep=waits.append)
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError("should re-raise after last attempt")
```

Usage: `retry(lambda: fetch(url), exceptions=(ConnectionError, TimeoutError))`. Narrow `exceptions` in real use, since the default retries on everything, including bugs.

